+      if (state.phase === 'charge' || state.phase === 'main') { render(); return; }
+    }
+    const chosen = new Set();
+    function paint() {
+      const cards = state.player.hand.map(function (card) {
+        return cardMarkup(card, { modalAction: 'toggle-mulligan', selected: chosen.has(card.uid) });
